{
  "headline": "Boca Raton to Host 2nd Annual Mobility Workshop on Oct. 29",
  "dek": "Residents can learn about current transportation projects and view student presentations at Florida Atlantic University.",
  "body_md": "The City of Boca Raton will host its 2nd Annual Mobility Workshop on Thursday, October 29, 2026, from 4:30 to 7:00 pm at Florida Atlantic University.\n\nThe free event will take place in Gangal Hall at FAU’s Engineering East building. Pre-registration is required due to limited capacity. The workshop is presented in partnership with the FAU College of Engineering & Computer Science and the FAU Chapter of the Institute of Transportation Engineers.\n\nAttendees can connect with local agencies and partners during an Exhibit Hall from 4:30 to 5:30 p.m. Participating organizations include the Palm Beach Metropolitan Planning Organization (MPO), Florida Department of Transportation (FDOT), Circuit, and the City of Boca Raton’s Fire Rescue Services Department and Office of Sustainability.\n\nFrom 5:30 to 6:00 p.m., the City’s Public Works & Engineering staff will provide updates on current mobility programs. Student poster presentations featuring ideas for the future of mobility will follow from 6:00 to 7:00 p.m.",
  "beat": "government",
  "source_record_ids": [
    "dc5febf4-5aea-42d5-855f-eff3361b2264"
  ],
  "claims": [
    {
      "text": "The City of Boca Raton will host its 2nd Annual Mobility Workshop on Thursday, October 29, 2026",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "The event is from 4:30 to 7:00 pm",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "The event is at Florida Atlantic University (FAU)",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "The workshop is hosted at Gangal Hall at FAU’s Engineering East building",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "The workshop is free",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "Pre-registration is required due to limited capacity",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "The workshop is presented in partnership with the FAU College of Engineering & Computer Science and the FAU Chapter of the Institute of Transportation Engineers",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "Participating organizations include the Palm Beach Metropolitan Planning Organization (MPO), Florida Department of Transportation (FDOT), Circuit, and the City of Boca Raton’s Fire Rescue Services Department and Office of Sustainability",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "4:30–5:30 p.m. is the Exhibit Hall",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "5:30–6:00 p.m. features City Mobility Project Updates from the City’s Public Works & Engineering staff",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    },
    {
      "text": "6:00–7:00 p.m. features Student Poster Presentations where FAU students share ideas for the future of mobility",
      "record_id": "dc5febf4-5aea-42d5-855f-eff3361b2264"
    }
  ]
}

