89068f33424a7248637e4b27.text:
{
  "headline": "Mayor Andy Thomson to Host Community Town Hall",
  "dek": "Boca Raton residents can meet with the Mayor on Wednesday, October 14, at the Spanish River Library to discuss city initiatives and local issues.",
  "body_md": "Boca Raton Mayor Andy Thomson will host a community town hall meeting on Wednesday, October 14, offering residents a chance to discuss city initiatives and local issues.\n\nThe event is scheduled from 6:00 to 7:30 p.m. on the mezzanine of the Spanish River Library, located at 1501 NW Spanish River Blvd.\n\nThe town hall is designed to provide an informal setting for open dialogue between residents and the Mayor. With several city initiatives and projects underway and on the horizon, the gathering will give community members an opportunity to ask questions, share feedback, and gain a better understanding of current and future city plans.\n\nMedia members planning to attend must RSVP by Tuesday, October 13, to Ileana Olmsted by emailing [email protected] or calling 561-393-7788.",
  "beat": "government",
  "source_record_ids": [
    "56ca2409-487c-4885-801e-f511bb2eac4a"
  ],
  "claims": [
    {
      "text": "Mayor Andy Thomson will host a Town Hall meeting on Wednesday, October 14",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    },
    {
      "text": "Offering residents an opportunity to hear directly from the Mayor about what’s happening in Boca Raton, upcoming City initiatives, and issues that matter to the community",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    },
    {
      "text": "The Town Hall is designed to provide an informal setting for open dialogue between residents and the Mayor",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    },
    {
      "text": "With several City initiatives and projects underway and on the horizon, the event will give residents an opportunity to ask questions, share feedback, and gain a better understanding of the City's current and future plans and projects",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    },
    {
      "text": "6:00 – 7:30 p.m.",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    },
    {
      "text": "Spanish River Library, Mezzanine, 1501 NW Spanish River Blvd., Boca Raton, FL 33431",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    },
    {
      "text": "Media RSVP by Tuesday, October 13 to Ileana Olmsted at [email protected] or 561-393-7788",
      "record_id": "56ca2409-487c-4885-801e-f511bb2eac4a"
    }
  ]
}

