4858f92e9d2db5f3b5f43cba.text:
{
  "headline": "Boca Raton City Council Adopts $1.03 Billion Budget for Fiscal Year 2026-27",
  "dek": "The $1,031,450,000 budget maintains the current operating millage rate and funds six new firefighter-paramedic positions.",
  "body_md": "The Boca Raton City Council voted 4-1 on Tuesday, Sept. 22, 2026, to adopt the City's Fiscal Year 2026-27 budget totaling $1,031,450,000. The new budget takes effect Oct. 1, 2026.\n\nCouncil Member Marc Wigder cast the dissenting vote.\n\nThe adopted operating millage rate is set at 3.6788 mills, which remains unchanged from the current year. The spending plan funds 1,812 full-time positions. Among these are six new firefighter-paramedic positions designated for Boca Raton Fire Rescue Station 8.\n\nIn the capital budget, $14,200,000 has been allocated for the resurfacing of Palmetto Park Road between Military Trail and Federal Highway. That roadwork project is scheduled to begin in January 2027.\n\nResidents looking for more details can view the full budget document on the City's Financial Services page.",
  "beat": "government",
  "source_record_ids": [
    "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
  ],
  "claims": [
    {
      "text": "The Boca Raton City Council voted 4-1 on Tuesday, Sept. 22, 2026, to adopt the City's Fiscal Year 2026-27 budget of $1,031,450,000",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    },
    {
      "text": "the budget takes effect Oct. 1, 2026",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    },
    {
      "text": "Council Member Marc Wigder cast the dissenting vote",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    },
    {
      "text": "The adopted operating millage rate is 3.6788 mills, unchanged from the current year",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    },
    {
      "text": "The budget funds 1,812 full-time positions, including six new firefighter-paramedic positions for Boca Raton Fire Rescue Station 8",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    },
    {
      "text": "The capital budget includes $14,200,000 for the resurfacing of Palmetto Park Road between Military Trail and Federal Highway, scheduled to begin in January 2027",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    },
    {
      "text": "The full budget document is available on the City's Financial Services page",
      "record_id": "5b0a753f-96da-4183-8c0f-8cef2e62cd20"
    }
  ]
}

