    },
    {
      "text": "The bakery's new location is 2200 N. Federal Highway, Suite 104",
      "record_id": "9808dad4-3599-4a1f-8e3a-385e1b72597f"
    },
    {
      "text": "The bakery is owned by Elena and David Moreau",
      "record_id": "9808dad4-3599-4a1f-8e3a-385e1b72597f"
    },
    {
      "text": "The bakery employs 12 people",
      "record_id": "9808dad4-3599-4a1f-8e3a-385e1b72597f"
    },
    {
      "text": "The bakery is open Tuesday through Sunday from 7 a.m. to 3 p.m.",
      "record_id": "9808dad4-3599-4a1f-8e3a-385e1b72597f"
    },
    {
      "text": "The City of Boca Raton Office of Economic Development helped the business through the City's Business Ambassador program",
