{
  "headline": "Police arrest man in Mizner Park jewelry store theft",
  "dek": "Mark Delaney was arrested after three watches were stolen from a jewelry store in Mizner Park.",
  "body_md": "Boca Raton Police Services arrested a Boca Raton man on Thursday, Oct. 8, 2026, in connection with the theft of three watches from a jewelry store in Mizner Park. The theft occurred on Oct. 2.\n\nMark Delaney, 34, of Boca Raton, was identified through surveillance video, according to police. Officers arrested him without incident at his home in the 900 block of NW 3rd Avenue.\n\nPolice said the watches, valued at $18,500, were recovered. Delaney was charged with grand theft and taken to the Palm Beach County Jail.\n\nThe investigation is ongoing. Authorities stated that anyone with information may call Detective Sgt. Ana Ruiz at 561-338-1302. The release was issued by the Boca Raton Police Services Public Information Office.",
  "beat": "public-safety",
  "source_record_ids": [
    "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
  ],
  "claims": [
    {
      "text": "Boca Raton Police Services arrested Mark Delaney, 34, of Boca Raton, on Thursday, Oct. 8, 2026",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "theft of three watches from a jewelry store in Mizner Park on Oct. 2",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "Delaney was identified through surveillance video",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "arrested without incident at his home in the 900 block of NW 3rd Avenue",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "charged with grand theft",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "taken to the Palm Beach County Jail",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "the watches, valued at $18,500, were recovered",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "The investigation is ongoing",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "Anyone with information may call Detective Sgt. Ana Ruiz at 561-338-1302",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    },
    {
      "text": "This release is issued by Boca Raton Police Services Public Information Office",
      "record_id": "4e9b5a23-b2ca-42ae-822f-22b65d46f150"
    }
  ]
}

