d88946a52034f6e7380d7a46.text:
{
  "headline": "Boca Raton homeowner faces daily fines over pool fence violations",
  "dek": "The Code Compliance Special Magistrate ordered a daily fine for an unrepaired pool fence.",
  "body_md": "The City of Boca Raton Code Compliance Special Magistrate on Wednesday, Oct. 7, 2026, fined homeowner Linda Park $250 a day, beginning Nov. 1, 2026, if the pool fence at her property in the 1200 block of SW 12th Avenue is not repaired.\n\nCity inspectors cited the property on Aug. 14, 2026, after finding a broken gate latch and a gap in the fence that did not meet the Florida Building Code's pool barrier requirements. The magistrate gave the owner until Oct. 31 to make repairs.\n\nCode Compliance hearings are held monthly at City Hall and are open to the public. Residents may report code concerns through the City's MyBoca app or by calling 561-393-7934.",
  "beat": "government",
  "source_record_ids": [
    "7f01b364-2ae0-4a08-8938-7867ec659222"
  ],
  "claims": [
    {
      "text": "The City of Boca Raton Code Compliance Special Magistrate on Wednesday, Oct. 7, 2026, fined homeowner Linda Park $250 a day",
      "record_id": "7f01b364-2ae0-4a08-8938-7867ec659222"
    },
    {
      "text": "beginning Nov. 1, 2026, if the pool fence at her property in the 1200 block of SW 12th Avenue is not repaired",
      "record_id": "7f01b364-2ae0-4a08-8938-7867ec659222"
