cb554f6108ec4eb49c931064.text:
{
  "headline": "Boca Raton Issues Precautionary Boil Water Notice for East Boca",
  "dek": "A water main break caused a loss of pressure affecting customers on NE 20th Street, NE 6th Avenue and NE 7th Avenue.",
  "body_md": "The City of Boca Raton Utility Services Department has issued a precautionary boil water notice for part of east Boca Raton following a water main break.\n\nThe water main break occurred on Tuesday, Oct. 13, 2026, and caused a loss of pressure in the area. The notice affects customers on NE 20th Street between NE 5th Avenue and Federal Highway, including all addresses on NE 6th Avenue and NE 7th Avenue in that area.\n\nAs a precaution, affected customers should boil all water used for drinking, cooking, making ice, brushing teeth and washing dishes for at least one minute before use.\n\nThe boil water notice will remain in effect until two consecutive days of bacteriological tests show the water is safe. Customers will be notified when the notice is lifted.\n\nResidents with questions may direct them to Utility Services at 561-338-7310.",
  "beat": "government",
  "source_record_ids": [
    "ce6d904c-ab6a-4002-8635-26b07791b6a1"
  ],
  "claims": [
    {
      "text": "The City of Boca Raton Utility Services Department has issued a precautionary boil water notice for part of east Boca Raton",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    },
    {
      "text": "A water main break on Tuesday, Oct. 13, 2026, caused a loss of pressure",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    },
    {
      "text": "The notice applies to customers on NE 20th Street between NE 5th Avenue and Federal Highway, including all addresses on NE 6th Avenue and NE 7th Avenue in that area",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    },
    {
      "text": "Affected customers should boil all water used for drinking, cooking, making ice, brushing teeth and washing dishes for at least one minute before use",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    },
    {
      "text": "The notice will remain in effect until two consecutive days of bacteriological tests show the water is safe",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    },
    {
      "text": "Customers will be notified when it is lifted",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    },
    {
      "text": "Questions may be directed to Utility Services at 561-338-7310",
      "record_id": "ce6d904c-ab6a-4002-8635-26b07791b6a1"
    }
  ]
}

