28b71af12366200e00107fb1.text:
{
  "headline": "State Inspectors Temporarily Close Sea Breeze Grill in Boca Raton",
  "dek": "The downtown restaurant was temporarily closed on Friday, Oct. 9, 2026, after state inspectors found 14 violations.",
  "body_md": "The Florida Division of Hotels and Restaurants ordered Sea Breeze Grill, located at 101 E. Palmetto Park Road, to close temporarily on Friday, Oct. 9, 2026.\n\nAn inspector found 14 violations during the visit, which included four high-priority violations for rodent activity in the kitchen and food held at unsafe temperatures.\n\nThe restaurant was allowed to reopen on Saturday, Oct. 10, after a follow-up inspection found that the high-priority violations had been corrected.\n\nInspection reports are public records published by the Florida Department of Business and Professional Regulation. The City of Boca Raton shares this notice as a public service, and the inspection was conducted by the state.",
  "beat": "business",
  "source_record_ids": [
    "1b2d6bff-57cb-48ea-89d1-23c5e88d3b61"
  ],
  "claims": [
    {
      "text": "The Florida Division of Hotels and Restaurants ordered Sea Breeze Grill, 101 E. Palmetto Park Road, Boca Raton, to close temporarily on Friday, Oct. 9, 2026",
      "record_id": "1b2d6bff-57cb-48ea-89d1-23c5e88d3b61"
    },
    {
      "text": "an inspector found 14 violations, including four high-priority violations for rodent activity in the kitchen and food held at unsafe temperatures",
      "record_id": "1b2d6bff-57cb-48ea-89d1-23c5e88d3b61"
    },
    {
      "text": "The restaurant was allowed to reopen on Saturday, Oct. 10, after a follow-up inspection found the high-priority violations corrected",
      "record_id": "1b2d6bff-57cb-48ea-89d1-23c5e88d3b61"
    },
    {
      "text": "Inspection reports are public records published by the Florida Department of Business and Professional Regulation",
      "record_id": "1b2d6bff-57cb-48ea-89d1-23c5e88d3b61"
    },
    {
      "text": "The City of Boca Raton shares this notice as a public service; the inspection was conducted by the state",
      "record_id": "1b2d6bff-57cb-48ea-89d1-23c5e88d3b61"
    }
  ]
}

