0cc37b4a6f3cea0b58b46440.text:
{
  "headline": "State Attorney Drops Grand Theft Charge in Mizner Park Jewelry Store Case",
  "dek": "Police say the investigation into the watch theft remains open and are asking for the public's help.",
  "body_md": "The Office of the State Attorney for the 15th Judicial Circuit has dropped a grand theft charge against a Boca Raton man who was previously arrested in connection with a theft at a Mizner Park jewelry store, according to Boca Raton Police Services.\n\nBoca Raton Police Services was notified on Wednesday, Oct. 14, 2026, that the State Attorney's Office filed a notice of nolle prosequi for Mark Delaney, 34, of Boca Raton. Delaney had been arrested on Oct. 8 in connection with the theft of watches from a jewelry store located in Mizner Park.\n\nPolice announced that while the charge has been dropped, the investigation into the theft remains open.\n\nAuthorities are asking anyone with information regarding the incident to come forward. Tips can be directed to Detective Sgt. Ana Ruiz at 561-338-1302. The release was issued by the Boca Raton Police Services Public Information Office.",
  "beat": "public-safety",
  "source_record_ids": [
    "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
  ],
  "claims": [
    {
      "text": "Boca Raton Police Services was notified on Wednesday, Oct. 14, 2026",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "Office of the State Attorney for the 15th Judicial Circuit has dropped the grand theft charge against Mark Delaney",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "Mark Delaney is 34 and of Boca Raton",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "Mark Delaney was arrested Oct. 8 in connection with the theft of watches from a jewelry store in Mizner Park",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "State Attorney's Office filed a notice of nolle prosequi",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "Investigation into the theft remains open",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "Anyone with information may call Detective Sgt. Ana Ruiz at 561-338-1302",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    },
    {
      "text": "Release is issued by Boca Raton Police Services Public Information Office",
      "record_id": "b90b7401-c17a-47e1-8f92-79f34d9ca2bc"
    }
  ]
}

